import {footProbeOffsets} from './city-free-walk.mjs?v=p21-b407-s039-reuse';
import {createReservation} from './city-e045-reservation.mjs?v=p21-b407-s039-reuse';

const activations=new WeakMap(),cell=p=>p.slice(0,2).join(','),finite=p=>Array.isArray(p)&&p.length===3&&p.slice(0,2).every(Number.isFinite)&&typeof p[2]==='string';

export async function createE046P03Receiver({read,load,addSprites,lightAnchors}){
 const base='assets/e046-p03-v1/',data=await read(base+'receiver.json');
 if(data.schema!==1||JSON.stringify(data.foot.probes)!==JSON.stringify(footProbeOffsets)||data.renderer.doorHeightPixels<65||data.renderer.doorHeightPixels>68)throw Error('E046 P03 receiver profile changed');
 const reservation=createReservation(data),files=data.art.layers,images=await Promise.all([files.body,files.roofHidden,files.foreground,files.nightEmission].map(name=>load(base+name)));
 if(images.some(image=>(image.cwSourceWidth||image.width)!==data.art.canvas[0]||(image.cwSourceHeight||image.height)!==data.art.canvas[1]))throw Error('E046 P03 artwork dimensions changed');
 const points=data.regions[0].worldPolygon,xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),rect=[Math.min(...xs)+.5,Math.min(...ys)+.5,Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys)];
 lightAnchors[data.renderer.sourceAsset]=data.renderer.lightAnchors;
 const[o]=addSprites([[data.renderer.spriteID,images[0],data.art.worldPivot,data.art.anchor,data.art.uniformScale,rect,{sceneryKind:'joined-premises',sourceAsset:data.renderer.sourceAsset,collisionMode:'explicit-e045-reservation',nightEmission:images[3]}]]);
 o.roofHidden={...o,im:images[1]};o.actorFootCutaway=Object.freeze({width:48,centerHeight:.25,heightFactor:1.15,groundOnly:true});o.e045DepthContract=Object.freeze(data.depth);o.e046P03Foreground=images[2];
 let discarded=false;
 return Object.freeze({id:data.id,data,reservation,object:o,discard(list){if(discarded)return;discarded=true;for(let i=list.length-1;i>=0;i--)if(list[i]===o)list.splice(i,1);delete lightAnchors[data.renderer.sourceAsset];},report:()=>({ready:!discarded,id:data.id,foundationResidualNativePixels:data.art.foundationResidualNativePixels,doorHeightPixels:data.renderer.doorHeightPixels,lightAnchors:data.renderer.lightAnchors.length,roofLayerSeparate:true,foregroundLayerSeparate:true,interactiveInterior:false,creativeAcceptance:false})});
}

export function activateE046P03({world,ground,receiver,originalMembers,streetPath}){
 if(!receiver)return null;if(activations.has(world))throw Error('E046 P03 reservation already active');
 const{reservation,data}=receiver,plan=reservation.membershipPlan(world.members,originalMembers),remove=[...plan.centres,...plan.footOnly].sort((a,b)=>a.key.localeCompare(b.key)),expected=data.expectedRemoval.slice().sort((a,b)=>a.key.localeCompare(b.key));
 if(plan.originalConflicts.length||JSON.stringify(remove)!==JSON.stringify(expected)||remove.length!==12||remove.some(r=>r.edges.length!==1||r.edges[0]!=='E046'))throw Error('E046 P03 membership/original route preflight changed');
 const priorPoint=ground.clearPoint,priorTraverse=world.canTraverse,priorNeighbours=world.neighbours,priorReport=ground.report,priorDoor=world.doors.get(data.door.gameID),retainedOriginal=[...originalMembers].filter(([,ids])=>ids.has('E046'));
 if(retainedOriginal.length!==116||priorDoor)throw Error('E046 P03 original route or door identity changed');
 const gates=reservation.gates({basePointClear:p=>priorPoint(p),baseSegmentClear:(a,b)=>!priorTraverse||priorTraverse(a,b)}),standing=p=>finite(p)&&world.members.get([Math.round(p[0]),Math.round(p[1])].join(','))?.has(p[2])&&gates.canStand(p)&&world.waterCollision.pointClear(p,[p[2]])&&world.waterCollision.standClear(p,p[2]);
 const saved=remove.map(r=>({key:r.key,member:world.members.get(r.key),extra:ground.extra.get(r.key),blocked:ground.blocked.has(r.key)})),traversable=(a,b)=>finite(a)&&finite(b)&&world.members.get([Math.round(a[0]),Math.round(a[1])].join(','))?.has(a[2])&&world.members.get([Math.round(b[0]),Math.round(b[1])].join(','))?.has(b[2])&&gates.canTraverse(a,b);
 const probeReach=Math.max(...footProbeOffsets.flat().map(Math.abs)),bounds=reservation.regions[0].bounds.map((v,i)=>v+(i<2?-probeReach:probeReach)),sweeps=new Map();let sweepHits=0,sweepMisses=0;
 const canTraverse=(a,b)=>{const dx=b[0]-a[0],dy=b[1]-a[1],local=Math.max(a[0],b[0])>=bounds[0]&&Math.min(a[0],b[0])<=bounds[2]&&Math.max(a[1],b[1])>=bounds[1]&&Math.min(a[1],b[1])<=bounds[3];if(!local)return !priorTraverse||priorTraverse(a,b);const cacheable=finite(a)&&finite(b)&&Number.isInteger(a[0])&&Number.isInteger(a[1])&&Number.isInteger(dx)&&Number.isInteger(dy)&&Math.max(Math.abs(dx),Math.abs(dy))<=1,key=cacheable?a.join(',')+'>'+b.join(','):null;if(key&&sweeps.has(key)){sweepHits++;return sweeps.get(key);}sweepMisses++;const okay=!!traversable(a,b);if(key){if(sweeps.size>=512)sweeps.delete(sweeps.keys().next().value);sweeps.set(key,okay);}return okay;};
 try{
  for(const r of remove){world.members.delete(r.key);ground.extra.delete(r.key);ground.blocked.add(r.key);}ground.clearPoint=gates.pointClear;world.canTraverse=canTraverse;
  const connected=new Set(),todo=[[52,225,'E046']];for(let i=0;i<todo.length;i++){const p=todo[i],key=p.join(',');if(connected.has(key))continue;connected.add(key);for(const q of world.neighbours(p))if(q[2]==='E046'&&!connected.has(q.join(',')))todo.push(q);}
  if(retainedOriginal.some(([k])=>!connected.has(k+',E046'))||!connected.has(data.door.stance.join(','))||!standing(data.door.stance))throw Error('E046 P03 route or doorway connectivity changed');
  const route=streetPath(world,[52,225,'E046'],data.door.stance.slice(0,2),'E046');if(route===null||route.some(p=>!standing(p)))throw Error('E046 P03 doorway has no full-foot-clear route');
  const door=Object.freeze({game_id:data.door.gameID,lf_id:'ORIGINAL INFILL',name:data.door.name,position:Object.freeze(data.door.stance.slice(0,2)),edge:'E046',held:false,exteriorOnly:true,source_instance:data.renderer.spriteID,source_asset:data.renderer.sourceAsset,door_height_pixels:data.renderer.doorHeightPixels,threshold_world:Object.freeze(data.door.thresholdWorld.slice()),case_function_preserved:'An unnamed workshop dwelling opens onto the existing E046 approach. Its door is shut.'});world.doors.set(door.game_id,door);
  const candidates=[...world.members].filter(([,ids])=>ids.has('E046')).map(([k])=>[...k.split(',').map(Number),'E046']).filter(standing);
  const state=Object.freeze({id:data.id,door,route,removed:remove,canStand:standing,recover(record){const result=reservation.proposeRecovery(record,candidates,{isValidState:p=>world.members.get(cell(p))?.has(p[2]),basePointClear:p=>priorPoint(p)&&world.waterCollision.pointClear(p,[p[2]||'E046']),reachable:p=>connected.has(p.join(','))});return result?{...result,reason:result.reason.replace('E045 proposed reservation','E046 P03 reservation')}:result;},report:()=>({active:true,id:data.id,removed:remove.length,originalRetained:retainedOriginal.length,door:door.game_id,doorRouteSteps:route.length,foundationResidualNativePixels:data.art.foundationResidualNativePixels,doorHeightPixels:data.renderer.doorHeightPixels,sweepCache:sweeps.size,sweepHits,sweepMisses,creativeAcceptance:false})});
  ground.report=()=>{const report=priorReport();return{...report,rectangularFootprints:report.rectangularFootprints??report.footprints,footprints:report.footprints+1,polygonReservations:[...(report.polygonReservations||[]),state.report()]};};activations.set(world,state);return state;
 }catch(error){for(const r of saved){world.members.set(r.key,r.member);if(r.extra!==undefined)ground.extra.set(r.key,r.extra);else ground.extra.delete(r.key);if(r.blocked)ground.blocked.add(r.key);else ground.blocked.delete(r.key);}if(priorDoor)world.doors.set(data.door.gameID,priorDoor);else world.doors.delete(data.door.gameID);ground.clearPoint=priorPoint;world.canTraverse=priorTraverse;world.neighbours=priorNeighbours;ground.report=priorReport;throw error;}
}
